        {
            try
            {
                await db.SaveChangesAsync(ct);

                var positionResults = orderedPositions
                    .Select(p => new BookingPositionResult(p.RowLabel, p.ColumnNumber, ToSummary(priceCategories[p.PriceCategoryId])))
